package com.example.gameworkbench.service.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.example.gameworkbench.common.enums.ErrorCode; import com.example.gameworkbench.common.exception.BusinessException; import com.example.gameworkbench.dto.admin.UpdateUserAccessRequest; import com.example.gameworkbench.entity.*; import com.example.gameworkbench.mapper.*; import com.example.gameworkbench.service.*; import com.example.gameworkbench.vo.admin.AdminUserVO; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.List;
@Service @RequiredArgsConstructor public class AdminUserServiceImpl implements AdminUserService { private final SysUserMapper users; private final UserRoleAuditMapper audits; private final RedisService redis;
 public Page<AdminUserVO> list(long actor,int n,int size,String username,String role,String status){ Page<SysUser> page=users.selectPage(new Page<>(Math.max(1,n),Math.min(100,Math.max(1,size))),new LambdaQueryWrapper<SysUser>().like(username!=null&&!username.isBlank(),SysUser::getUsername,username).eq(role!=null&&!role.isBlank(),SysUser::getRole,role).eq(status!=null&&!status.isBlank(),SysUser::getStatus,status).orderByDesc(SysUser::getId)); Page<AdminUserVO> result=new Page<>(page.getCurrent(),page.getSize(),page.getTotal()); result.setRecords(page.getRecords().stream().map(u->vo(u,actor)).toList()); return result; }
 @Transactional public AdminUserVO update(long actor,long target,UpdateUserAccessRequest r){ if(actor==target) throw new BusinessException(ErrorCode.INVALID_PARAM); SysUser u=users.selectById(target); if(u==null) throw new BusinessException(ErrorCode.USER_NOT_FOUND); String role=r.getRole()==null?u.getRole():r.getRole(); String status=r.getStatus()==null?u.getStatus():r.getStatus(); if("ADMIN".equals(u.getRole()) && (!"ADMIN".equals(role)||!"NORMAL".equals(status)) && users.selectCount(new LambdaQueryWrapper<SysUser>().eq(SysUser::getRole,"ADMIN").eq(SysUser::getStatus,"NORMAL"))<=1) throw new BusinessException(ErrorCode.INVALID_PARAM); if(role.equals(u.getRole())&&status.equals(u.getStatus())) return vo(u,actor); UserRoleAudit a=new UserRoleAudit(); a.setActorUserId(actor);a.setTargetUserId(target);a.setOperation(!role.equals(u.getRole())?"ROLE_CHANGED":"STATUS_CHANGED");a.setBeforeRole(u.getRole());a.setAfterRole(role);a.setBeforeStatus(u.getStatus());a.setAfterStatus(status);a.setCreatedAt(LocalDateTime.now()); u.setRole(role);u.setStatus(status);users.updateById(u);audits.insert(a);redis.delete(String.valueOf(target));return vo(u,actor); }
 public List<UserRoleAudit> audits(long target){ return audits.selectList(new LambdaQueryWrapper<UserRoleAudit>().eq(UserRoleAudit::getTargetUserId,target).orderByDesc(UserRoleAudit::getCreatedAt).last("limit 100")); }
 private AdminUserVO vo(SysUser u,long actor){ return AdminUserVO.builder().id(u.getId()).username(u.getUsername()).role(u.getRole()).status(u.getStatus()).createdAt(u.getCreatedAt()).lastLoginAt(u.getLastLoginAt()).self(u.getId()==actor).build(); }
}
